From 19134f2bf02ab8efee7443da60ca808ad7d05dd6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:06:04 +0100
Subject: [PATCH] plugins/nightlight: add shortcuts to change the night
 temperature

Changing the Night Light temperature meant opening System Settings every
time. Add "Increase" and "Decrease Night Light Temperature" global
shortcuts that move the night temperature by 100 K and show it in an OSD.

BUG: 515832
---
 src/plugins/nightlight/nightlightmanager.cpp | 39 ++++++++++++++++++++
 src/plugins/nightlight/nightlightmanager.h   |  1 +
 2 files changed, 40 insertions(+)

diff --git a/src/plugins/nightlight/nightlightmanager.cpp b/src/plugins/nightlight/nightlightmanager.cpp
index baa28220ef..77efccfcf3 100644
--- a/src/plugins/nightlight/nightlightmanager.cpp
+++ b/src/plugins/nightlight/nightlightmanager.cpp
@@ -37,6 +37,7 @@ namespace KWin

 static const int QUICK_ADJUST_DURATION = 2000;
 static const int TEMPERATURE_STEP = 50;
+static const int NIGHT_TEMPERATURE_SHORTCUT_STEP = 100;

 NightLightManager::NightLightManager()
     : m_settings(std::make_unique<NightLightSettings>(kwinApp()->config()))
@@ -80,6 +81,24 @@ NightLightManager::NightLightManager()
     KGlobalAccel::setGlobalShortcut(toggleAction, QList<QKeySequence>());
     connect(toggleAction, &QAction::triggered, this, &NightLightManager::toggle);

+    QAction *increaseAction = new QAction(this);
+    increaseAction->setProperty("componentName", QStringLiteral("kwin"));
+    increaseAction->setObjectName(QStringLiteral("Increase Night Light Temperature"));
+    increaseAction->setText(i18nc("@action", "Increase Night Light Temperature"));
+    KGlobalAccel::setGlobalShortcut(increaseAction, QList<QKeySequence>());
+    connect(increaseAction, &QAction::triggered, this, [this] {
+        adjustNightTemperature(NIGHT_TEMPERATURE_SHORTCUT_STEP);
+    });
+
+    QAction *decreaseAction = new QAction(this);
+    decreaseAction->setProperty("componentName", QStringLiteral("kwin"));
+    decreaseAction->setObjectName(QStringLiteral("Decrease Night Light Temperature"));
+    decreaseAction->setText(i18nc("@action", "Decrease Night Light Temperature"));
+    KGlobalAccel::setGlobalShortcut(decreaseAction, QList<QKeySequence>());
+    connect(decreaseAction, &QAction::triggered, this, [this] {
+        adjustNightTemperature(-NIGHT_TEMPERATURE_SHORTCUT_STEP);
+    });
+
     connect(kwinApp()->outputBackend(), &OutputBackend::outputAdded, this, &NightLightManager::hardReset);

     connect(kwinApp()->session(), &Session::activeChanged, this, [this](bool active) {
@@ -126,6 +145,26 @@ void NightLightManager::toggle()
     m_isGloballyInhibited ? inhibit() : uninhibit();
 }

+void NightLightManager::adjustNightTemperature(int delta)
+{
+    const int temperature = std::clamp(m_nightTargetTemperature + delta, MIN_TEMPERATURE, DEFAULT_DAY_TEMPERATURE);
+    if (temperature != m_nightTargetTemperature) {
+        m_settings->setNightTemperature(temperature);
+        m_settings->save();
+        reconfigure();
+    }
+
+    QDBusMessage message = QDBusMessage::createMethodCall(
+        QStringLiteral("org.kde.plasmashell"),
+        QStringLiteral("/org/kde/osdService"),
+        QStringLiteral("org.kde.osdService"),
+        QStringLiteral("showText"));
+    message.setArguments(
+        {QStringLiteral("redshift-status-on"),
+         i18nc("@info:OSD %1 is a color temperature in Kelvin", "Night Light Temperature: %1 K", temperature)});
+    QDBusConnection::sessionBus().asyncCall(message);
+}
+
 bool NightLightManager::isInhibited() const
 {
     return m_inhibitReferenceCount;
diff --git a/src/plugins/nightlight/nightlightmanager.h b/src/plugins/nightlight/nightlightmanager.h
index 33e139b4f9..4e06cd2626 100644
--- a/src/plugins/nightlight/nightlightmanager.h
+++ b/src/plugins/nightlight/nightlightmanager.h
@@ -287,6 +287,7 @@ Q_SIGNALS:
 private:
     void readConfig();
     void hardReset();
+    void adjustNightTemperature(int delta);
     void slowUpdate(int targetTemperature);
     void resetAllTimers();
     int currentTargetTemperature() const;
-- 
